namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-001", "TRACK-HEIGHT: the vehicles sample the object under each probe in the original's modes (0x450EA0: surface records, terrain + the header's +0xA0, the instance mesh), but the surface-record mode is taken for a model with a dummy record of type bit 2 (the instance block's bit 8 the original tests is not read), the terrain is the mean ground of the tile's (or bumper cell's) four corners instead of the triangle sampler 0x4527F0 at the probe, faces count from either side and are baked with the full rest transforms, a cell with no track gives the terrain, the instance-mesh mode reads every 0x8000 face of the model, and the Halloween and space kart stations (face-sampled station models) use the straight piece's floor; a tile stands on the mean ground of its four cells"),
		("TRACK-002", "TRACK-HMP: the .hmp height profile is the original's per-object height map (loader 0x451640 from the mesh loader 0x4629D0, rebuilt from the mesh by 0x451880 when missing or mis-sized); the vehicles' sampler does not read it (0x4511A0 samples faces or the terrain sampler 0x4527F0, the landscape's interpolated heights of the grid at [0x7A0854]+0x6C, 0 off the map, TRACK-001) and neither do OpenTPW's vehicles; the kit parses it; the map (+0xCC) is read by the cell-height lookup 0x452AE0 (the cell owner's map byte x 100/255 plus its base height, else the landscape; callers 0x45CDC0, 0x532FC0, 0x536CA0, 0x5370E0 and the tour code 0x55ABF0, 0x55C350, 0x55CC00, TOUR-005), and whether any other code reads the map is not traced"),
		("TRACK-003", "TRACK-OFFSET: each 20-unit tile turns about its own centre, where the original instances at the origin cell plus a one-cell offset by rotation (the Bumper.*Adjust keys are the controller-reference offsets of the ride placement 0x529E10, not a mesh pivot)"),
		("TRACK-004", "TRACK-X2LINK: the multi-bit flow links of water crossings (0x14, 0x41, 0x50) choose the second crossing family as traced, but OpenTPW writes them by OR-ing the headings of a crossing walked twice; the circuit walk 0x52A970 writes +0xD only at corners (the leaving heading, 0x52B1A9..0x52B1F5), and the junction writers among the other callers of 0x5227E0 (the type-25 walk 0x52BA50 takes the first linked arm by rotation at a junction) are not traced"),
		("TRACK-005", "TRACK-STATION: the station is two tiles on the footprint's first two tile columns along the heading in the rows beside the entrance, the circuit starts at the first, and the station and finish buoys sit behind the station reference; the original's station is the line of 0x52A1A0 (two tiles of type 13 or 18 from the attraction cell, with the walk start and exit cell per rotation), which reads the attraction that is constructed at the placement's cursor cell (OpenTPW's anchor, 0x818C3C written at 0x528E12 from 0x528B44) plus the untraced per-rotation offset of 0x4D9CC0 (type +0x4B0, 0x529F86); that offset, the attraction's +8/+0xC and the line modes 0x80, 0x82 and 0x83 are not traced"),
		("TRACK-006", "TRACK-MSG: the advisor and event messages after a circuit walk (ids 0xCC, 0x151, 0xB8, 0xD6) are not shown; OpenTPW posts its own status line"),
		("TRACK-007", "TRACK-DEMOLISH: removing a water ride clears the tiles laid for it and pays nothing; the original demolition 0x527EE0 replays the track tool from both station sides (flag 0x81B46C = 1), during which ClearCell 0x53B280 earns (0x4D0190 at 0x53B622) the kart or water cell cost (0x52FB60/0x52FB80) x the ride's scrap percentage (0x4E2290) / 100 for cleared track cells under conditions on the cell's +0x20 word and thing id (0x53B54A..0x53B57F) that are not decoded, and then charges (Spend 0x4D01F0, 0x52814A..0x528179) 2 x the cell cost x the scrap percentage / 100 once; both run only for a type with Info.HasQueue (def+0x40), whose queue is replayed first and charged the queue cell cost x the scrap percentage / 100 once"),
		("TRACK-008", "TRACK-ADDON: jumps and tunnels (map flag 0x10, section kinds 12 and 13, their run counters and values) are deferred"),
		("TRACK-010", "TRACK-BRIDGE: a straight tile is a bridge when it replaced path cells; the original 0x538A92 bridges a kart or water tile with at most two arms and no corner (single-arm ends included) while a path or queue lies in the map layer under any of its four cells, re-testing when paths change, and only type 25 tests map types 2, 7 and 30 (cells outside the park); OpenTPW's track replaces the paths, so it remembers them, and only exact straights qualify"),
		("TRACK-014", "TRACK-WALK: OpenTPW's walk also fails a tile without an arm toward the flow and a three- or four-arm tile without an arm ahead, stops after as many steps as the layer has tiles plus the station, numbers the tiles from 1 and writes only when committing; the original 0x52A970 keeps the heading on every non-corner cell without testing arms, fails a cell that is not a track type (0x53AD30) or has fewer than two arms (0x52B20C), and a three-arm cell when the cell two ahead has type 0 or is a track cell without arms while the heading is 0x01 (a literal bit test, 0x52B234..0x52B280); it has no step limit, arrives on reaching the start cell from any side (0x52B2DE) and in both modes writes +0xD at corners and the 0-based step to +0x24 (0x52B295)"),
		("TRACK-018", "TRACK-ANIM: the pieces are static; the water texture animation (BUMP 17) is stored but not played and the tee pieces show all four arms"),
		("TRACK-019", "TRACK-SCOPE: the module tick, frame counter, vehicle and object pools and object searches are module-wide as in the original (0x546C80), but the module ticks where the first controller's ride advances (the rides placed before it run their script step first; the original ticks before every script), a park-resume save from before the shared pools restores their order from the restore (controllers by attraction id), a vehicle whose foreign object is rebuilt loses it (the original keeps a stale pointer), and the bumper cars' chase candidates and drop-in overlap test read their own ride's cars only"),
		("TRACK-026", "TRACK-HEADS: a kart's riders are drawn as head sprites at the head dummies (class 0x100000B1, numbers 1 and 2) through the ride-head renderer in the original's seat order (rider list order, 0x549C60); the draw internals (0x0044B410, 0x00475A10) and the boarding guest between BUMP 1 and the car's creation are not traced"),
	};
}
